SET @sName = 'bx_artificer';


-- PAGE: service blocks
UPDATE `sys_pages_blocks` SET `content`='<style>\r\n.bx-artificer-splash .bx-form-element .bx-btn.bx-btn-primary {\r\n    width: 100%;\r\n}\r\n</style>\r\n<div class="bx-artificer-splash relative max-w-7xl ring-1 ring-gray-200 dark:ring-gray-800 bg-gray-50 dark:bg-gray-900 shadow-sm rounded divide-y divide-gray-200 dark:divide-gray-800 my-2 lg:my-3 mx-2 lg:mx-3 xl:mx-auto overflow-hidden">\r\n    <div class="absolute top-0 left-0 w-full h-full dark:hidden z-1">\r\n        <img src="<bx_image_url:cover-default.svg />" class="object-cover h-full w-full" />\r\n    </div>\r\n    <div class="absolute top-0 left-0 w-full h-full hidden dark:block z-1">\r\n        <img src="<bx_image_url:cover-default-dark.svg />" class="object-cover h-full w-full" />\r\n    </div>\r\n    <div class="relative pb-8 z-2">\r\n        <div class="mt-6">\r\n            <div class="mx-auto max-w-7xl">\r\n                <div class="lg:grid lg:grid-cols-12 lg:gap-8">\r\n                    <div class="px-6 lg:px-8 text-center md:max-w-2xl md:mx-auto lg:col-span-6 lg:text-left lg:flex lg:items-center">\r\n                      <div>\r\n                        <h1 class="text-5xl tracking-tight font-bold text-gray-800 dark:text-white xl:text-6xl">\r\n                            <span class="block"><bx_text:_bx_artificer_txt_splash_welcome_l1 /></span>\r\n                            <span class="block pb-3 bg-clip-text text-transparent bg-gradient-to-r from-green-500 to-blue-500 sm:pb-5"><bx_text:_bx_artificer_txt_splash_welcome_l2 /></span>\r\n                        </h1>\r\n                        <p class="mt-3 text-base font-normal text-gray-700 dark:text-gray-300 sm:mt-5 sm:text-xl lg:text-lg xl:text-xl">\r\n                            <span class="block"><bx_text:_bx_artificer_txt_splash_welcome_l3 /></span>\r\n                        </p>\r\n                        <p class="mt-3 text-base font-light text-gray-700 dark:text-gray-300 sm:mt-5 sm:text-sm lg:text-xs xl:text-base">\r\n                            <span class="block"><bx_text:_bx_artificer_txt_splash_welcome_l4 /></span>\r\n                        </p>\r\n                      </div>\r\n                    </div>\r\n                    <div class="relative mt-16 px-6 lg:mt-0 lg:px-8 lg:col-span-6 lg:ml-4">\r\n                        <div class="opacity-80 relative max-w-lg ring-1 ring-white dark:ring-gray-700 sm:overflow-hidden bg-gray-50 dark:bg-gray-800 shadow-2xl rounded divide-y divide-gray-300 dark:divide-gray-700 m-2 lg:m-3  mx-auto bg-opacity-80">\r\n                            <div class="p-8">\r\n                                <div>\r\n                                    <h2 class="text-2xl font-semibold text-gray-800 dark:text-gray-200"><bx_text:_bx_artificer_txt_splash_login_title /></h2>\r\n                                    <div class="mt-6">{{~system:login_form:TemplServiceLogin["no_join_text no_auth_buttons"]~}}</div>\r\n                                    <div class="mt-6 relative">\r\n                                        <div class="absolute inset-0 flex items-center" aria-hidden="true">\r\n                                            <div class="w-full border-t border-gray-300 dark:border-gray-700"></div>\r\n                                        </div>\r\n                                    </div>\r\n                                    <div class="pt-6">\r\n                                        <a class="bx-btn w-full flex justify-center py-2 px-4 border border-transparent rounded shadow-sm text-sm font-medium text-white bg-green-600 hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500" href="__join_link__"><bx_text:_bx_artificer_txt_splash_login_join /></a>\r\n                                    </div>\r\n                                    <div class="mt-4">{{~system:member_auth_code:TemplServiceLogin~}}</div>\r\n                                </div>\r\n                            </div>\r\n                            <div class="px-4 py-6 bg-white dark:bg-gray-900 bg-opacity-50 sm:px-10">\r\n                                <p class="text-xs leading-5 text-gray-500">{{~bx_artificer:get_splash_marker["login_agreement"]~}}</p>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>' WHERE `object`='sys_home' AND `cell_id`=0 AND `title`='_bx_artificer_page_block_title_splash_lite';
