     </div>\r\n                            </div>\r\n                            <div class="px-4 py-6 bg-white dark:bg-gray-900 bg-opacity-50 sm:px-10">\r\n                                <p class="text-xs leading-5 text-gray-500">{{~bx_artificer:get_splash_marker["login_agreement"]~}}</p>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n<div class="bg-gray-100 dark:bg-gray-900 pt-12 sm:pt-16">\r\n    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">\r\n        <div class="max-w-4xl mx-auto text-center">\r\n            <h2 class="text-3xl font-semibold text-gray-900 dark:text-gray-100 sm:text-4xl"><bx_text:_bx_artificer_txt_splash_stats_l1 /></h2>\r\n            <p class="mt-3 text-xl font-light text-gray-500 sm:mt-4"><bx_text:_bx_artificer_txt_splash_stats_l2 /></p>\r\n        </div>\r\n    </div>\r\n    <div class="mt-10 pb-12 bg-white dark:bg-black sm:pb-16">\r\n        <div class="relative">\r\n            <div class="absolute inset-0 h-1/2 bg-gray-100 dark:bg-gray-900 "></div>\r\n            <div class="relative max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">\r\n                <div class="max-w-7xl mx-auto">\r\n                    <dl class="rounded-lg bg-white dark:bg-gray-800 shadow-lg sm:grid sm:grid-cols-3">\r\n                        <div class="flex flex-col border-b border-gray-100 dark:border-gray-700 p-4 pt-5 text-center sm:border-0 sm:border-r">\r\n                            <dt class="order-2 mt-2 text-lg leading-6 font-light text-gray-500"><bx_text:_bx_artificer_txt_splash_stats_c1 /></dt>\r\n                            <dd class="order-1 text-3xl font-bold text-blue-600">{{~bx_artificer:get_splash_marker["members"]~}}</dd>\r\n                        </div>\r\n                        <div class="flex flex-col border-t border-b border-gray-100 dark:border-gray-900 p-4 pt-5  text-center sm:border-0 sm:border-